<template>
	<div class="add-update-preview">
		<el-form
			class="add-update-form"
			ref="ruleForm"
			:model="ruleForm"
			:rules="rules"
			label-width="160px"
			>
			<el-form-item class="add-item" label="求职账号" prop="qiuzhizhanghao">
				<el-input v-model="ruleForm.qiuzhizhanghao" 
					placeholder="求职账号" clearable :disabled=" false  ||ro.qiuzhizhanghao"></el-input>
			</el-form-item>
			<el-form-item class="add-item" label="求职姓名" prop="qiuzhixingming">
				<el-input v-model="ruleForm.qiuzhixingming" 
					placeholder="求职姓名" clearable :disabled=" false  ||ro.qiuzhixingming"></el-input>
			</el-form-item>
			<el-form-item class="add-item" label="性别" prop="xingbie">
				<el-input v-model="ruleForm.xingbie" 
					placeholder="性别" clearable :disabled=" false  ||ro.xingbie"></el-input>
			</el-form-item>
			<el-form-item class="add-item" label="联系电话" prop="lianxidianhua">
				<el-input v-model="ruleForm.lianxidianhua" 
					placeholder="联系电话" clearable :disabled=" false  ||ro.lianxidianhua"></el-input>
			</el-form-item>
			<el-form-item class="add-item" label="头像" v-if="type!='cross' || (type=='cross' && !ro.touxiang)" prop="touxiang">
				<file-upload
					tip="点击上传头像"
					action="file/upload"
					:limit="3"
					:multiple="true"
					:fileUrls="ruleForm.touxiang?ruleForm.touxiang:''"
					@change="touxiangUploadChange"
					></file-upload>
			</el-form-item>
			<el-form-item class="add-item" v-else label="头像" prop="touxiang">
				<img v-if="ruleForm.touxiang.substring(0,4)=='http'" class="upload-img" v-bind:key="index" :src="ruleForm.touxiang.split(',')[0]">
				<img v-else class="upload-img" v-bind:key="index" v-for="(item,index) in ruleForm.touxiang.split(',')" :src="baseUrl+item">
			</el-form-item>
			<el-form-item class="add-item" label="专业" prop="zhuanye">
				<el-input v-model="ruleForm.zhuanye" 
					placeholder="专业" clearable :disabled=" false  ||ro.zhuanye"></el-input>
			</el-form-item>
			<el-form-item class="add-item"  label="学历" prop="xueli">
				<el-select v-model="ruleForm.xueli" placeholder="请选择学历" :disabled=" false  ||ro.xueli" >
					<el-option
						v-for="(item,index) in xueliOptions"
						:key="index"
						:label="item"
						:value="item">
					</el-option>
				</el-select>
			</el-form-item>
			<el-form-item class="add-item" label="出生日期" prop="chushengriqi">
				<el-date-picker
					:disabled=" false  ||ro.chushengriqi"
					format="yyyy 年 MM 月 dd 日"
					value-format="yyyy-MM-dd"
					v-model="ruleForm.chushengriqi" 
					type="date"
					placeholder="出生日期">
				</el-date-picker> 
			</el-form-item>
			<el-form-item class="add-item" label="求职意向" prop="qiuzhiyixiang">
				<el-input v-model="ruleForm.qiuzhiyixiang" 
					placeholder="求职意向" clearable :disabled=" false  ||ro.qiuzhiyixiang"></el-input>
			</el-form-item>
			<el-form-item class="add-item"  label="意向职位" prop="yixiangzhiwei">
				<el-select v-model="ruleForm.yixiangzhiwei" placeholder="请选择意向职位" :disabled=" false  ||ro.yixiangzhiwei" >
					<el-option
						v-for="(item,index) in yixiangzhiweiOptions"
						:key="index"
						:label="item"
						:value="item">
					</el-option>
				</el-select>
			</el-form-item>
			<el-form-item class="add-item" label="意向城市" prop="yixiangchengshi">
				<el-input v-model="ruleForm.yixiangchengshi" 
					placeholder="意向城市" clearable :disabled=" false  ||ro.yixiangchengshi"></el-input>
			</el-form-item>
			<el-form-item class="add-item" label="薪资要求" prop="xinziyaoqiu">
				<el-input v-model="ruleForm.xinziyaoqiu" 
					placeholder="薪资要求" clearable :disabled=" false  ||ro.xinziyaoqiu"></el-input>
			</el-form-item>
			<el-form-item class="add-item" label="教育背景" prop="jiaoyubeijing">
				<el-input v-model="ruleForm.jiaoyubeijing" 
					placeholder="教育背景" clearable :disabled=" false  ||ro.jiaoyubeijing"></el-input>
			</el-form-item>
			<el-form-item class="add-item" label="获奖证书" prop="huojiangzhengshu">
				<el-input v-model="ruleForm.huojiangzhengshu" 
					placeholder="获奖证书" clearable :disabled=" false  ||ro.huojiangzhengshu"></el-input>
			</el-form-item>
			<el-form-item class="add-item" label="简历文件" prop="jianliwenjian">
				<file-upload
					tip="点击上传简历文件"
					action="file/upload"
					:limit="1"
					:type="3"
					:multiple="true"
					:fileUrls="ruleForm.jianliwenjian?ruleForm.jianliwenjian:''"
					@change="jianliwenjianUploadChange"
					></file-upload>
			</el-form-item>  
			<el-form-item class="add-item" label="工作经验" prop="gongzuojingyan">
				<el-input
					type="textarea"
					:rows="8"
					placeholder="工作经验"
					v-model="ruleForm.gongzuojingyan">
					</el-input>
			</el-form-item>
			<el-form-item class="add-item" label="项目经验" prop="xiangmujingyan">
				<el-input
					type="textarea"
					:rows="8"
					placeholder="项目经验"
					v-model="ruleForm.xiangmujingyan">
					</el-input>
			</el-form-item>
			<el-form-item class="add-item" label="个人技能" prop="gerenjineng">
				<el-input
					type="textarea"
					:rows="8"
					placeholder="个人技能"
					v-model="ruleForm.gerenjineng">
					</el-input>
			</el-form-item>
			<el-form-item class="add-item" label="自我评价" prop="ziwopingjia">
				<el-input
					type="textarea"
					:rows="8"
					placeholder="自我评价"
					v-model="ruleForm.ziwopingjia">
					</el-input>
			</el-form-item>

			<el-form-item class="add-btn-item">
				<el-button class="submitBtn"  type="primary" @click="onSubmit">
					<span class="icon iconfont icon-kaitongfuwu"></span>
					<span class="text">更新信息</span>
				</el-button>
				<el-button class="closeBtn" @click="back()">
					<span class="icon iconfont icon-shanchu1"></span>
					<span class="text">取消</span>
				</el-button>
			</el-form-item>
		</el-form>
	</div>
</template>

<script>
	export default {
		data() {
			return {
				id: '',
				baseUrl: '',
				ro:{
					qiuzhizhanghao : false,
					qiuzhixingming : false,
					xingbie : false,
					lianxidianhua : false,
					touxiang : false,
					zhuanye : false,
					xueli : false,
					chushengriqi : false,
					qiuzhiyixiang : false,
					yixiangzhiwei : false,
					yixiangchengshi : false,
					xinziyaoqiu : false,
					jiaoyubeijing : false,
					huojiangzhengshu : false,
					gongzuojingyan : false,
					xiangmujingyan : false,
					gerenjineng : false,
					ziwopingjia : false,
					jianliwenjian : false,
					storeupnum : false,
				},
				type: '',
				userTableName: localStorage.getItem('UserTableName'),
				ruleForm: {
					qiuzhizhanghao: '',
					qiuzhixingming: '',
					xingbie: '',
					lianxidianhua: '',
					touxiang: '',
					zhuanye: '',
					xueli: '',
					chushengriqi: '',
					qiuzhiyixiang: '',
					yixiangzhiwei: '',
					yixiangchengshi: '',
					xinziyaoqiu: '',
					jiaoyubeijing: '',
					huojiangzhengshu: '',
					gongzuojingyan: '',
					xiangmujingyan: '',
					gerenjineng: '',
					ziwopingjia: '',
					jianliwenjian: '',
					storeupnum: '',
				},
				xueliOptions: [],
				yixiangzhiweiOptions: [],


				rules: {
					qiuzhizhanghao: [
					],
					qiuzhixingming: [
					],
					xingbie: [
					],
					lianxidianhua: [
					],
					touxiang: [
					],
					zhuanye: [
					],
					xueli: [
					],
					chushengriqi: [
					],
					qiuzhiyixiang: [
					],
					yixiangzhiwei: [
					],
					yixiangchengshi: [
					],
					xinziyaoqiu: [
					],
					jiaoyubeijing: [
					],
					huojiangzhengshu: [
					],
					gongzuojingyan: [
					],
					xiangmujingyan: [
					],
					gerenjineng: [
					],
					ziwopingjia: [
					],
					jianliwenjian: [
					],
					storeupnum: [
						{ validator: this.$validate.isIntNumer, trigger: 'blur' },
					],
				},
				centerType: false,
			};
		},
		computed: {



		},
		components: {
		},
		created() {
			if(this.$route.query.centerType){
				this.centerType = true
			}
			//this.bg();
			let type = this.$route.query.type ? this.$route.query.type : '';
			this.init(type);
			this.baseUrl = this.$config.baseUrl;
			this.ruleForm.chushengriqi = this.getCurDate()
		},
		methods: {
			getMakeZero(s) {
				return s < 10 ? '0' + s : s;
			},
			// 下载
			download(file){
				window.open(`${file}`)
			},
			// 初始化
			init(type) {
				this.type = type;
				if(type=='cross'){
					var obj = JSON.parse(localStorage.getItem('crossObj'));
					for (var o in obj){
						if(o=='qiuzhizhanghao'){
							this.ruleForm.qiuzhizhanghao = obj[o];
							this.ro.qiuzhizhanghao = true;
							continue;
						}
						if(o=='qiuzhixingming'){
							this.ruleForm.qiuzhixingming = obj[o];
							this.ro.qiuzhixingming = true;
							continue;
						}
						if(o=='xingbie'){
							this.ruleForm.xingbie = obj[o];
							this.ro.xingbie = true;
							continue;
						}
						if(o=='lianxidianhua'){
							this.ruleForm.lianxidianhua = obj[o];
							this.ro.lianxidianhua = true;
							continue;
						}
						if(o=='touxiang'){
							this.ruleForm.touxiang = obj[o].split(",")[0];
							this.ro.touxiang = true;
							continue;
						}
						if(o=='zhuanye'){
							this.ruleForm.zhuanye = obj[o];
							this.ro.zhuanye = true;
							continue;
						}
						if(o=='xueli'){
							this.ruleForm.xueli = obj[o];
							this.ro.xueli = true;
							continue;
						}
						if(o=='chushengriqi'){
							this.ruleForm.chushengriqi = obj[o];
							this.ro.chushengriqi = true;
							continue;
						}
						if(o=='qiuzhiyixiang'){
							this.ruleForm.qiuzhiyixiang = obj[o];
							this.ro.qiuzhiyixiang = true;
							continue;
						}
						if(o=='yixiangzhiwei'){
							this.ruleForm.yixiangzhiwei = obj[o];
							this.ro.yixiangzhiwei = true;
							continue;
						}
						if(o=='yixiangchengshi'){
							this.ruleForm.yixiangchengshi = obj[o];
							this.ro.yixiangchengshi = true;
							continue;
						}
						if(o=='xinziyaoqiu'){
							this.ruleForm.xinziyaoqiu = obj[o];
							this.ro.xinziyaoqiu = true;
							continue;
						}
						if(o=='jiaoyubeijing'){
							this.ruleForm.jiaoyubeijing = obj[o];
							this.ro.jiaoyubeijing = true;
							continue;
						}
						if(o=='huojiangzhengshu'){
							this.ruleForm.huojiangzhengshu = obj[o];
							this.ro.huojiangzhengshu = true;
							continue;
						}
						if(o=='gongzuojingyan'){
							this.ruleForm.gongzuojingyan = obj[o];
							this.ro.gongzuojingyan = true;
							continue;
						}
						if(o=='xiangmujingyan'){
							this.ruleForm.xiangmujingyan = obj[o];
							this.ro.xiangmujingyan = true;
							continue;
						}
						if(o=='gerenjineng'){
							this.ruleForm.gerenjineng = obj[o];
							this.ro.gerenjineng = true;
							continue;
						}
						if(o=='ziwopingjia'){
							this.ruleForm.ziwopingjia = obj[o];
							this.ro.ziwopingjia = true;
							continue;
						}
						if(o=='jianliwenjian'){
							this.ruleForm.jianliwenjian = obj[o];
							this.ro.jianliwenjian = true;
							continue;
						}
						if(o=='storeupnum'){
							this.ruleForm.storeupnum = obj[o];
							this.ro.storeupnum = true;
							continue;
						}
					}
				}else if(type=='edit'){
					this.info()
				}
				// 获取用户信息
				this.$http.get(this.userTableName + '/session', {emulateJSON: true}).then(res => {
					if (res.data.code == 0) {
						var json = res.data.data;
						if((json.qiuzhizhanghao!=''&&json.qiuzhizhanghao) || json.qiuzhizhanghao==0){
							this.ruleForm.qiuzhizhanghao = json.qiuzhizhanghao;
							this.ro.qiuzhizhanghao = true;
						}
						if((json.qiuzhixingming!=''&&json.qiuzhixingming) || json.qiuzhixingming==0){
							this.ruleForm.qiuzhixingming = json.qiuzhixingming;
							this.ro.qiuzhixingming = true;
						}
						if((json.xingbie!=''&&json.xingbie) || json.xingbie==0){
							this.ruleForm.xingbie = json.xingbie;
							this.ro.xingbie = true;
						}
						if((json.lianxidianhua!=''&&json.lianxidianhua) || json.lianxidianhua==0){
							this.ruleForm.lianxidianhua = json.lianxidianhua;
							this.ro.lianxidianhua = true;
						}
						if((json.touxiang!=''&&json.touxiang) || json.touxiang==0){
							this.ruleForm.touxiang = json.touxiang;
							this.ro.touxiang = true;
						}
					}
				});
				this.xueliOptions = "高中及以上,大专及以上,本科及以上,硕士生,研究生,博士生,博士后,其他".split(',')
				this.$http.get('option/gangweifenlei/gangweileixing', {emulateJSON: true}).then(res => {
					if (res.data.code == 0) {
						this.yixiangzhiweiOptions = res.data.data;
					}
				});

				if (localStorage.getItem('raffleType') && localStorage.getItem('raffleType') != null) {
					localStorage.removeItem('raffleType')
					setTimeout(() => {
						this.onSubmit()
					}, 300)
				}
			},

			// 多级联动参数
			// 多级联动参数
			info() {
				this.$http.get(`jianlixinxi/detail/${this.$route.query.id}`, {emulateJSON: true}).then(res => {
					if (res.data.code == 0) {
						this.ruleForm = res.data.data;
					}
				});
			},
			// 提交
			async onSubmit() {
				await this.$refs["ruleForm"].validate(async valid => {
					if(valid) {
						if(this.type=='cross'){
							var statusColumnName = localStorage.getItem('statusColumnName');
							var statusColumnValue = localStorage.getItem('statusColumnValue');
							if(statusColumnName && statusColumnName!='') {
								var obj = JSON.parse(localStorage.getItem('crossObj'));
								if(!statusColumnName.startsWith("[")) {
									for (var o in obj){
										if(o==statusColumnName){
											obj[o] = statusColumnValue;
										}
									}
									var table = localStorage.getItem('crossTable');
									await this.$http.post(table+'/update', obj).then(res => {});
								}
							}
						}


						await this.$http.post(`jianlixinxi/${this.ruleForm.id?'update':this.centerType?'save':'add'}`, this.ruleForm).then(async res => {
							if (res.data.code == 0) {
								this.$message({
									message: '操作成功',
									type: 'success',
									duration: 1500,
									onClose: () => {
										this.$router.go(-1);
										
									}
								});
							} else {
								this.$message({
									message: res.data.msg,
									type: 'error',
									duration: 1500
								});
							}
						});
					}
				});
			},
			// 获取uuid
			getUUID () {
				return new Date().getTime();
			},
			// 返回
			back() {
				this.$router.go(-1);
			},
			touxiangUploadChange(fileUrls) {
				this.ruleForm.touxiang = fileUrls.replace(new RegExp(this.$config.baseUrl,"g"),"");
			},
			jianliwenjianUploadChange(fileUrls) {
				this.ruleForm.jianliwenjian = fileUrls.replace(new RegExp(this.$config.baseUrl,"g"),"");
			},
		}
	};
</script>

