			padding: 30px;
			margin: 0 0 0 30px;
			background: #FFFFFF;
			flex: none;
			display: flex;
			width: 620px;
			position: relative;
			order: 2;
			.info {
				padding: 0;
				margin: 0;
				background: #fff;
				flex: 1;
				.title-item {
					padding: 0 0 0 20px;
					box-shadow: inset 0px 4px 10px 0px rgba(178,178,178,0.3);
					margin: 0 0 10px 0;
					background: #FFFFFF;
					display: flex;
					justify-content: space-between;
					align-items: center;
					height: 70px;
					.detail-title {
						color: #333;
						font-weight: 700;
						font-size: 16px;
					}
				}
				.item {
					padding: 5px;
					box-shadow: inset 0px 4px 10px 0px rgba(178,178,178,0.3);
					margin: 0 0 10px 0;
					color: #000000;
					background: #FFF;
					display: flex;
					justify-content: space-between;
					.lable {
						padding: 0 10px;
						color: #9E9E9E;
						white-space: nowrap;
						width: auto;
						font-size: 14px;
						line-height: 40px;
						text-align: right;
						height: 40px;
					}
					.text {
						padding: 8px 10px 0 0;
						color: #000000;
						flex: 1;
						font-size: 14px;
						line-height: 24px;
						height: auto;
					}
					.price {
						color: #f00;
					}
					.bold {
						font-weight: bold;
					}
					.link {
						cursor: pointer;
						text-decoration: underline;
					}
					.uploadBtn {
						border-radius: 10px;
						padding: 0px 10px;
						margin: 0px;
						color: #fff;
						background: #896785;
						text-decoration: none;
						width: 100px;
						font-size: 14px;
						line-height: 40px;
						text-align: center;
						height: 40px;
					}
					.uploadBtn:hover {
					}
				}
				.btn_box {
					padding: 10px 0;
					display: flex;
					flex-wrap: wrap;
				}
				.editBtn {
